import{c as t,Q as a,j as o,m as s}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Loop Engineering Clearly Explained","description":"","frontmatter":{"url":"https://x.com/akshay_pachaar/status/2069118430582866051","title":"Loop Engineering Clearly Explained","author":"Akshay Pachaar","archived":"2026-06-27T00:00:00.000Z","handle":"@akshay_pachaar","published":"2026-06-22T00:00:00.000Z","stats":"1540 likes · 220 retweets · 3303 bookmarks · 903812 views","tags":["loop-engineering","agentic-ai","harness","context-management","tool-design"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-22-@akshay_pachaar-866051.md","filePath":"research/tweets/2026-06-22-@akshay_pachaar-866051.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-06-22-@akshay_pachaar-866051.md"};function i(r,e,h,l,d,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="loop-engineering-clearly-explained-—-akshay-pachaar" tabindex="-1">Loop Engineering Clearly Explained — @akshay_pachaar <a class="header-anchor" href="#loop-engineering-clearly-explained-—-akshay-pachaar" aria-label="Permalink to &quot;Loop Engineering Clearly Explained — @akshay_pachaar&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/akshay_pachaar/status/2069118430582866051" target="_blank" rel="noreferrer">https://x.com/akshay_pachaar/status/2069118430582866051</a><strong>作者</strong>：Akshay Pachaar（@akshay_pachaar） <strong>發布日期</strong>：2026-06-22 <strong>收錄日期</strong>：2026-06-27 <strong>類型</strong>：Twitter Article <strong>統計</strong>：1540 likes · 220 retweets · 3303 bookmarks · 903812 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Half your feed is suddenly saying the same thing. Stop prompting your agents, start engineering loops. Boris Cherny, the person who built Claude Code, said it plainly: &quot;I don&#39;t prompt Claude anymore. I have loops that are running. My job is to write loops.&quot; The person who builds one of the most popular coding agents on earth doesn&#39;t prompt it. So what is he doing instead? That&#39;s the whole idea behind loop engineering. Now let&#39;s break down why it&#39;s harder than it looks.</p><h1 id="first-the-loop-itself" tabindex="-1">First, the loop itself <a class="header-anchor" href="#first-the-loop-itself" aria-label="Permalink to &quot;First, the loop itself&quot;">​</a></h1><p>An agent isn&#39;t a magic box. At its core, it&#39;s a plain loop:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    response </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> model(context)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> response.has_tool_calls():</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        results </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run_tools(response.tool_calls)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        context </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> results</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        break</span></span></code></pre></div><p>The model reads the context. It asks to call a tool. You run the tool and feed the result back. The model reads again, and this repeats until it stops asking for tools. Model → tools → context → repeat. Here&#39;s the part that surprises people. This loop is already solved. Every serious agent framework lands on roughly these six lines. Nobody is competing on the while statement. So if the loop is trivial, what is everyone actually engineering?</p><h1 id="the-work-moved-outside-the-model" tabindex="-1">The work moved outside the model <a class="header-anchor" href="#the-work-moved-outside-the-model" aria-label="Permalink to &quot;The work moved outside the model&quot;">​</a></h1><p>The center of gravity in AI keeps drifting away from the model itself.</p><ul><li>Prompt engineering. The words you send.</li><li>Context engineering. Everything the model sees, not just your instructions.</li><li>Harness engineering. The code around the model that runs tools, tracks state, and handles errors.</li><li>Loop engineering. The autonomous cycle that drives the whole thing toward a goal.</li></ul><p>Each layer wraps the one before it. You didn&#39;t stop caring about prompts. You just realized the prompt is one small piece of a much bigger system. LangChain puts it cleanly. Agent = Model + Harness. If you&#39;re not the model, you&#39;re the harness. And here&#39;s the finding that should reorder your priorities. The harness now matters more than the model. Teams have kept the model fixed, changed only the code around it, and jumped from the middle of a benchmark into the top five. Same brain, different loop. Loop engineering is the discipline of building everything that brain runs inside. Let me show you the parts that actually break.</p><h1 id="hard-part-1-knowing-when-to-stop" tabindex="-1">Hard part 1: knowing when to stop <a class="header-anchor" href="#hard-part-1-knowing-when-to-stop" aria-label="Permalink to &quot;Hard part 1: knowing when to stop&quot;">​</a></h1><p>This is the problem nobody warns you about. When an agent stops asking for tools, it has ended its turn. That is not the same as finishing the job. Picture a coding agent. It writes some code, glances around, sees that progress was made, and announces it&#39;s done. The tests still fail. It declared victory anyway. A terminal message ends the turn, not the task. Confusing those two is the most common way loops go wrong. Good loops stop for the right reasons, so you layer several brakes:</p><ul><li>Max iterations. A hard cap so a stuck agent can&#39;t run forever.</li><li>Budget and time limits. A ceiling on tokens, money, and seconds.</li><li>No-progress detection. If it repeats the same call with the same arguments, it&#39;s spinning.</li><li>A real completion check. An automated condition proving the job is done.</li></ul><p>That last one carries the weight. &quot;Done&quot; should mean the tests pass, not the agent feeling good about its work.</p><h1 id="hard-part-2-keeping-the-context-clean" tabindex="-1">Hard part 2: keeping the context clean <a class="header-anchor" href="#hard-part-2-keeping-the-context-clean" aria-label="Permalink to &quot;Hard part 2: keeping the context clean&quot;">​</a></h1><p>Long loops rot from the inside. The more turns an agent takes, the more junk piles into its context, like old tool outputs, dead ends, and stale reasoning. Model performance drops as that pile grows. The field calls it context rot. A loop makes it spiral. A rotted context produces a worse decision, which adds more noise, which rots the context further. People call this the doom loop, and you&#39;ve felt it. The agent gets dumber the longer it runs. You fight it by treating context as a budget, not a bucket:</p><ul><li>Compaction. Summarize the conversation when it gets long, then continue from the summary.</li><li>Offloading. Push huge outputs to a file and keep only the slice you need.</li><li>Sub-agents. Hand a messy subtask to a separate agent and let only its clean result return.</li></ul><p>The instinct is to keep everything, just in case. The skill is knowing what to throw away.</p><h1 id="hard-part-3-tools-the-agent-can-actually-use" tabindex="-1">Hard part 3: tools the agent can actually use <a class="header-anchor" href="#hard-part-3-tools-the-agent-can-actually-use" aria-label="Permalink to &quot;Hard part 3: tools the agent can actually use&quot;">​</a></h1><p>A loop is only as good as the tools inside it. Pile on a hundred tools and the agent loses track of which one to reach for. A tight set of focused, non-overlapping tools wins. Anthropic&#39;s rule of thumb is sharp. If a human engineer can&#39;t say for certain which tool fits, the agent has no chance. Two things matter more than people expect:</p><ul><li>Make writes safe to repeat. Loops retry, and if a retried &quot;create customer&quot; call makes a second customer, you&#39;ll wake up to duplicate records and double billing. Anything that changes state has to be safe to call twice.</li><li>Write error messages for the agent, not the human. A good error tells the agent what to do next. Before a tool ships, ask whether an LLM reading its error would know the next move.</li></ul><p>In a loop, an error isn&#39;t a dead end. It&#39;s the next instruction.</p><h1 id="hard-part-4-something-that-can-say-no" tabindex="-1">Hard part 4: something that can say no <a class="header-anchor" href="#hard-part-4-something-that-can-say-no" aria-label="Permalink to &quot;Hard part 4: something that can say no&quot;">​</a></h1><p>Autonomous loops have a quiet failure mode. An agent left alone tends to agree with itself. The sharpest comment in the whole debate nailed it. Designing the loop is half the job, and the other half is putting something in the loop that can say no, like a test, a type check, or a real error. A loop with no critic is just an agent nodding along to its own work. The fix is to separate the maker from the checker. One model does the work. A different check, often a separate model or a hard test, grades it. The worker doesn&#39;t grade its own homework.</p><h1 id="the-actual-shift" tabindex="-1">The actual shift <a class="header-anchor" href="#the-actual-shift" aria-label="Permalink to &quot;The actual shift&quot;">​</a></h1><p>Now Cherny&#39;s quote makes sense. Prompting is you steering the agent move by move. Loop engineering is you building the system that steers it, then stepping back. Your job changes from giving instructions to designing three things:</p><ol><li>The goal, written as success criteria the agent can check itself against.</li><li>The loop, with sane brakes so it stops well.</li><li>The verifier, so &quot;done&quot; is proven, not claimed.</li></ol><p>Andrej Karpathy captures the mindset. Don&#39;t tell the model what to do, give it success criteria and watch it go. He runs research loops overnight that tweak a script, test it, keep what works, and discard what doesn&#39;t, with himself nowhere in the loop. He arranges it once and hits go. That&#39;s the whole move. You stop being the hands and become the person who designs the machine.</p><h1 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h1><p>You don&#39;t need an overnight autonomous agent on day one. Build up to it:</p><ol><li>Start with the basic loop, and add a max-iteration cap, a timeout, and a cost ceiling right away.</li><li>Define &quot;done&quot; as an automated check before you begin, not a vibe afterward.</li><li>Protect the context. Compact long runs, offload big outputs, isolate messy subtasks.</li><li>Audit your tools. Keep them few and focused, make writes safe to repeat, and rewrite errors so an agent can act on them.</li><li>Put a critic in the loop. Only go fully hands-off once you trust the thing that says no.</li></ol><h1 id="the-takeaway" tabindex="-1">The takeaway <a class="header-anchor" href="#the-takeaway" aria-label="Permalink to &quot;The takeaway&quot;">​</a></h1><p>Loop engineering isn&#39;t a framework or a tool you install. It&#39;s a shift in where you aim your effort. The model is becoming a commodity. The loop around it is where the real engineering lives now. The best builders stopped asking &quot;what should I tell the agent to do?&quot; They started asking &quot;what system would do this without me?&quot; Answer that one well, and you&#39;ll stop prompting too.</p><p>[圖 1 — 來源: Key takeaways in loop engineering.]</p><hr><p>Thanks for reading! Cheers 😃 Akshay.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：從 Boris Cherny「我的工作是寫 loops」出發，拆解 Loop Engineering 四大難點：何時停止/上下文腐敗（doom loop）/工具冪等性與錯誤訊息設計/批判機制分離，附五步入門路徑。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li>基礎 agent loop（6 行 Python）已解決，工程競爭在 loop 外圍：Prompt → Context → Harness → Loop 四層依次包裹</li><li><strong>Hard part 1</strong>：「terminal message 結束的是 turn，不是 task」——停止條件要靠自動化完成檢查，非 agent 自我宣告</li><li><strong>Hard part 2</strong>：Context rot（doom loop）—— rotted context → worse decision → more noise → spiral；解法：Compaction/Offloading/Sub-agents</li><li><strong>Hard part 3</strong>：工具設計兩原則 — (a) idempotent writes（狀態變更操作必須安全重試），(b) error messages for the agent, not the human（錯誤訊息應告訴 agent 下一步做什麼）</li><li><strong>Hard part 4</strong>：分離 maker 與 checker；maker 不自評，verifier 獨立裁定 &quot;done&quot;</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>6 行 Python agent skeleton（while True + tool call cycle）</li><li>Agent = Model + Harness（LangChain 定義）</li><li>Harness 優化案例：同模型換 harness → benchmark 從中段跳至 top 5</li><li>Boris Cherny（Claude Code 作者）：「I don&#39;t prompt Claude anymore. My job is to write loops.」</li><li>Karpathy 過夜研究 loops：自主 tweak → test → keep/discard，無人在迴圈中</li><li>五步入門路徑（max-iter cap → define done → protect context → audit tools → add critic）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li>四大難點與 cc-workspace core.md 高度映射（unverified_success gate = Hard part 1；/compact = Hard part 2；APPLY gate = Hard part 4），但文章的具體技術表述（idempotency、agent-readable errors）補充了 workspace 目前缺少的細節</li><li>&quot;Context rot / doom loop&quot; 提供了比 workspace context-management.md 更清晰的失敗模式命名</li><li>篇幅聚焦在 why/what，缺少具體的 harness 實作範例；工具設計兩原則值得直接寫入規則</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>Idempotent writes、agent-readable errors、5 步路徑可直接套用；doom loop 命名強化 context-management.md</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>Context rot/doom loop 命名、&quot;turn ends ≠ task done&quot; 精確框架、工具錯誤訊息設計原則是 workspace 缺口</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>Cherny/Karpathy 引用有公信力，benchmark 跳升案例無具體數字；Twitter Article 上限 6</td></tr><tr><td>D. 技術深度 (15%)</td><td>8/10</td><td>Python skeleton、idempotency 邏輯、錯誤訊息設計原則、context 三種處理策略</td></tr><tr><td>E. 泛化性 (15%)</td><td>9/10</td><td>Framework/語言無關，適用任何 agentic 系統</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.35/10</strong></td><td>8×0.3+7×0.2+5×0.2+8×0.15+9×0.15 = 2.4+1.4+1.0+1.2+1.35</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：Idempotent writes + agent-readable errors + doom loop 三項原則可補充 core.md APPLY 段落及 subagent-strategy.md 工具設計規範</p>`,52)])])}const u=t(n,[["render",i]]);export{g as __pageData,u as default};
